scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_0').childNodes[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_1_0').childNodes[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 1
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_0_0 input:checked').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_1_0 input:checked').length == 1", "true");
    //Test step 2.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column5').childNodes[0].click()");
    //Verify step 2
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_0_0 input:checked').length == 0", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_1_0 input:checked').length == 0", "true");
    //Test step 3
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_plus')[0].click()");
    //Verify step 3.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_1_0').childNodes[0].checked", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
